  if (OpSchemaRegistry::Schema("PagedAttention", 1, "com.microsoft") == nullptr) {
      RegisterSchema(OpSchema("PagedAttention", "C:\\Users\\Administrator\\workspace\\onnxruntime\\onnxruntime\\core\\graph\\contrib_ops\\bert_defs.cc", 1452)
              .SetDomain("com.microsoft")
              .SinceVersion(1)
              .SetDoc("\nPaged Attention.\n\nThis op leverages a block-based KV cache to enable continuous batching for LLMs. Currently, it is designed to work with\nthe CUDA Execution Provider only.\n\nIn other attention ops, batch entries typically aren't of the same length, so they are padded.\nBelow is a batch with 3 sequences where * denotes a padding token.\n  Sequence_0:   0,  1*, 2*,  3*\n  Sequence_1:   4,  5,  6*,  7*\n  Sequence_2:   8,  9,  10,  11\n\nPagedAttention is designed to take in packed input, i.e., only the real tokens without padding.\nFor example, the input shown above will be packed into 3 tensors like below:\n - query ([q0, q4, q5, q8, q9, q10, q11])\n - key ([k0, k4, k5, k8, k9, k10, k11])\n - value ([v0, v4, v5, v8, v9, v10, v11])\n - cumulative_sequence_length: 0, 1, 1+2, 1+2+4\nThis packing omits padding tokens.\n\nThe query, key and value tensors contain result of hidden embedding of real tokens after input projections.\ncumulative_sequence_length records cumulated length of each sequence length.\n\n")
              .Input(0, "query", "Query with shape (num_tokens, hidden_size), or packed QKV with shape (num_tokens, d) where d is (num_heads * head_size + 2 * kv_num_heads * head_size).", "T", OpSchema::FormalParameterOption::Single, false)
              .Input(1, "key", "Key with shape (num_tokens, kv_hidden_size) ", "T", OpSchema::FormalParameterOption::Optional, false)
              .Input(2, "value", "Value with shape (num_tokens, kv_hidden_size)", "T", OpSchema::FormalParameterOption::Optional, false)
              .Input(3, "key_cache", "Block-based key cache with shape (num_blocks, block_size, kv_num_heads, head_size). This is updated in place within the op.", "T", OpSchema::FormalParameterOption::Single, false)
              .Input(4, "value_cache", "Block-based value cache with shape (num_blocks, block_size, kv_num_heads, head_size). This is updated in place within the op. This should be the same shape as key_cache.", "T", OpSchema::FormalParameterOption::Single, false)
              .Input(5, "cumulative_sequence_length", "A tensor with shape (batch_size + 1). It specifies the cumulative sequence lengths between the packed entries in Q/K/V.", "S", OpSchema::FormalParameterOption::Single, false)
              .Input(6, "past_seqlens", "A tensor with shape (batch_size). It specifies the past lengths of cached sequence in the KV cache.", "S", OpSchema::FormalParameterOption::Single, false)
              .Input(7, "block_table", "2D tensor with shape (batch_size, max_blocks_per_sequence) that maps each sequence in the batch to itscorresponding blocks in the KV cache.", "S", OpSchema::FormalParameterOption::Single, false)
              .Input(8, "cos_cache", "2D tensor with shape (max total seqlen, head_size / 2).", "T", OpSchema::FormalParameterOption::Optional, false)
              .Input(9, "sin_cache", "2D tensor with shape (max total seqlen, head_size / 2).", "T", OpSchema::FormalParameterOption::Optional, false)
              .Output(0, "output", "3D output tensor with shape (num_tokens, hidden_size)", "T", OpSchema::FormalParameterOption::Single, false)
              .Output(1, "key_cache_out", "Block-based key cache with shape (num_blocks, block_size, kv_num_heads, head_size). This is always the same tensor as key_cache.", "T", OpSchema::FormalParameterOption::Optional, false)
              .Output(2, "value_cache_out", "Block-based value cache with shape (num_blocks, block_size, kv_num_heads, head_size). This is always the same tensor as value_cache.", "T", OpSchema::FormalParameterOption::Optional, false)
              .Attr("local_window_size", "left_window_size for local attention (like Mistral). Default value is -1 meaning unused.", AttributeProto::INT, false)
              .Attr("num_heads", "Number of attention heads for q", AttributeProto::INT, true)
              .Attr("softcap", "Softcap value for attention weights. Default value is 0.", AttributeProto::FLOAT, false)
              .Attr("kv_num_heads", "Number of attention heads for k and v", AttributeProto::INT, true)
              .Attr("scale", "Custom scale will be used if specified. Default value is 1/sqrt(head_size)", AttributeProto::FLOAT, false)
              .Attr("do_rotary", "Whether to use rotary position embedding. Default value is 0.", AttributeProto::INT, false)
              .Attr("rotary_interleaved", "Rotate using interleaved pattern. Default value is 0 (False).", AttributeProto::INT, false)
              .TypeConstraint("T", {"tensor(float16)", "tensor(bfloat16)"}, "Constrain input and output to float tensors.")
              .TypeConstraint("S", {"tensor(int32)"}, "Constrain Positional inputs to int tensor.")
      );
  }

