  if (OpSchemaRegistry::Schema("Trilu", 1, "com.microsoft") == nullptr) {
      RegisterSchema(OpSchema("Trilu", "C:\\Users\\Administrator\\workspace\\onnxruntime\\onnxruntime\\core\\graph\\contrib_ops\\contrib_defs.cc", 830)
              .SetDomain("com.microsoft")
              .SinceVersion(1)
              .SetDoc("\n      Returns the upper or lower triangular part of a 2-D matrix, or batches of 2-D matrices. If the attribute \"upper\" is set to true,\n      the upper triangular matrix is retained. Lower triangular matrix is retained otherwise. Default value for upper is true.\n      Trilu takes one input tensor of shape [*, N, M], where * is zero or more batch dimensions. The upper triangular part consists\n      of the elements on and above the given diagonal (k). The lower triangular part consists of elements on and below the diagonal.\n      All other elements in the matrix are set to zero.\n      If k = 0, the triangular part on and above/below the main diagonal is retained.\n      If upper is set to true, a positive k retains the upper triangular matrix excluding k diagonals above\n      the main diagonal. A negative k value includes as many diagonals below the main diagonal.\n      If upper is set to false, a positive k retains the lower triangular matrix including k diagonals above\n      the main diagonal. A negative k value excludes as many diagonals below the main diagonal.\n      ")
              .Input(0, "X", "Input tensor of rank 2 or higher.", "T", OpSchema::FormalParameterOption::Single, false)
              .Input(1, "k", "A 0-D tensor containing a single value corresponding to the number diagonals above or the main diagonal to exclude or include.Default value is 0 if it's not specified.", "tensor(int64)", OpSchema::FormalParameterOption::Optional, false)
              .Output(0, "Y", "Output tensor of the same type and shape as the input tensor.", "T", OpSchema::FormalParameterOption::Single, false)
              .Attr("upper", "Boolean. Indicates whether upper or lower part of matrix is retained. Default is true.", AttributeProto::INT, false)
              .TypeConstraint("T", {"tensor(float16)", "tensor(float)", "tensor(double)", "tensor(bfloat16)", "tensor(uint8)", "tensor(uint16)", "tensor(uint32)", "tensor(uint64)", "tensor(int8)", "tensor(int16)", "tensor(int32)", "tensor(int64)", "tensor(bool)"}, "Constrain input and output types to all numeric tensors and bool tensors.")
      );
  }

